										:key="i"
										class="border-l-2 pl-3"
										:class="garisRiwayat(r.aksi)"
									>
										<div class="flex flex-wrap items-baseline gap-x-2">
											<span
												class="text-sm font-medium text-ui-ink-gray-900"
												>{{ r.aksi }}</span
											>
											<span class="text-xs text-ui-ink-gray-400">{{
												waktuRingkas(r.waktu)
											}}</span>
										</div>
										<p
											v-if="r.pelaku_nama"
											class="text-xs text-ui-ink-gray-500"
										>
											{{ r.pelaku_nama }}
										</p>
										<p
											v-if="r.catatan"
											class="mt-1 text-sm text-ui-ink-gray-600"
										>
											{{ r.catatan }}
										</p>
									</li>
								</ol>
							</div>
						</div>
					</div>
				</Transition>
			</div>
		</Transition>
	</div>
</template>

<script setup>
/**
 * Perbaikan Absen milik karyawan yang sedang login.
 *
 * Record-nya dibuat sistem tiap kali Kehadiran difinalkan bermasalah —
 * terlambat, tidak scan, pulang cepat, atau absen. Karyawan tidak pernah
 * membuatnya sendiri, hanya mengisi alasan dari lembar detail di halaman ini.
 *
 * Kartu di atas menghitung semua kejadian dalam periode cut-off (tidak ikut
 * filter status) dan sekaligus menjadi filter jenis.
 *
 * Query yang dikenali (dipakai tombol Perbaikan Absen di detail Kehadiran):
 *   ?tanggal=YYYY-MM-DD   saring ke satu hari (filter kalender terisi)
 *   ?buka=<name>          langsung buka lembar detail record itu
 *   ?kehadiran=<name>     tombol kembali menuju detail Kehadiran itu
 */
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { createResource } from 'frappe-ui'
import KalenderTanggal from '../components/KalenderTanggal.vue'
import {
	KELOMPOK,
	NAMA_BULAN,
	PILIHAN_STATUS,
	REJECTED,
	durasiMenit,
	garisRiwayat,
	jam,
	kelompok,
	keteranganKejadian,
	labelStatus,
	statusBadge,
	statusTitik,
	tanggalPanjang,
	tanggalRingkas,
	waktuRingkas,
} from '../data/perbaikanAbsenStatus'
import { refreshCsrfToken } from '../data/session'
import { notifyError, notifySuccess } from '../composables/toast'
import { useBackNavigation } from '../composables/useBackNavigation'

const route = useRoute()
const router = useRouter()

// Dibuka dari detail Kehadiran (?kehadiran=) -> kembali ke hari itu, bukan ke Home.
const asalKehadiran = String(route.query.kehadiran || '')
const { backTarget, backLabel } = useBackNavigation(
	asalKehadiran
		? { name: 'KehadiranDetail', params: { name: asalKehadiran } }
		: { name: 'Home' },
	asalKehadiran ? 'Kehadiran' : 'Home'
)

const PER_HALAMAN = 20
const MAKS_MB = 5

const hariIni = new Date()
// Null dulu: periode awal diambil dari server (periode cut-off yang berisi hari
// ini, atau yang berisi `?tanggal`).
const bulan = ref(null)
const tahun = ref(null)

const rows = ref([])
const ringkasan = ref({ kelompok: [], perlu_diisi: 0 })
const start = ref(0)
const hasMore = ref(false)
const loading = ref(false)
const error = ref('')

const kelompokAktif = ref('')
const status = ref('')
const tanggal = ref(
	/^\d{4}-\d{2}-\d{2}$/.test(route.query.tanggal || '') ? route.query.tanggal : ''
)
const sheetStatus = ref(false)
const kalenderBuka = ref(false)

const detail = ref(null)
const alasan = ref('')
const lampiran = ref('')
const galatKirim = ref('')
const mengirim = ref(false)
const mengunggah = ref(false)

const kartuJenis = computed(() => {
	const jumlah = Object.fromEntries(
		(ringkasan.value.kelompok || []).map((k) => [k.key, k.jumlah])
	)
	return KELOMPOK.map((k) => ({ ...k, jumlah: jumlah[k.key] || 0 }))
})

const labelPeriode = computed(() =>
	bulan.value ? `Periode ${NAMA_BULAN[bulan.value - 1]} ${tahun.value}` : 'Periode berjalan'
)

const bolehMaju = computed(
	() =>
		tahun.value < hariIni.getFullYear() ||
		(tahun.value === hariIni.getFullYear() && bulan.value < hariIni.getMonth() + 1)
)

const teksKosong = computed(() =>
	kelompokAktif.value || status.value || tanggal.value
		? 'Tidak ada yang cocok dengan filter ini.'
		: 'Tidak ada masalah absensi di periode ini. Pertahankan.'
)

const PLACEHOLDER = {
	Terlambat: 'Jelaskan kenapa Anda terlambat hari itu…',
	'Pulang Cepat': 'Jelaskan kenapa Anda pulang lebih awal hari itu…',
	'Tidak Scan IN': 'Jelaskan kenapa tidak ada scan masuk hari itu…',
	'Tidak Scan OUT': 'Jelaskan kenapa tidak ada scan pulang hari itu…',
	Absen: 'Jelaskan kenapa Anda tidak tercatat hadir hari itu…',
}
const placeholderAlasan = computed(() => PLACEHOLDER[detail.value?.jenis] || 'Tulis alasan Anda…')

function adaDurasi(row) {
	return ['Terlambat', 'Pulang Cepat'].includes(row?.jenis)
}

const list = createResource({
	url: 'juragan.api.portal.perbaikan_absen.get_daftar',
	auto: false,
	makeParams() {
		return {
			bulan: bulan.value ?? undefined,
			tahun: tahun.value ?? undefined,
			kelompok: kelompokAktif.value || undefined,
			status: status.value || undefined,
			tanggal: tanggal.value || undefined,
			limit: PER_HALAMAN,
			start: start.value,
		}
	},
	onSuccess(data) {
		const batch = data || []
		rows.value = start.value === 0 ? batch : rows.value.concat(batch)
		hasMore.value = batch.length === PER_HALAMAN
		loading.value = false
	},
	onError(err) {
		error.value = err?.messages?.[0] || err?.message || String(err)
		loading.value = false
	},
})

const ringkas = createResource({
	url: 'juragan.api.portal.perbaikan_absen.get_ringkasan',
	auto: false,
	makeParams() {
		return {
			bulan: bulan.value ?? undefined,
			tahun: tahun.value ?? undefined,
			tanggal: bulan.value == null ? tanggal.value || undefined : undefined,
		}
	},
	onSuccess(data) {
		if (!data) return
		ringkasan.value = data
		if (bulan.value == null && data.bulan) {
			bulan.value = data.bulan
			tahun.value = data.tahun
		}
	},
	// Wajib ada meski kosong: tanpa onError, handler global memunculkan toast
	// kedua untuk kegagalan yang sama — daftarnya sendiri sudah menjelaskan.
	onError() {},
})

const detailRes = createResource({
	url: 'juragan.api.portal.perbaikan_absen.get_detail',
	auto: false,
	onError(err) {
		notifyError(err, 'Gagal membuka detail')
	},
})

const kirimRes = createResource({
	url: 'juragan.api.portal.perbaikan_absen.kirim_alasan',
	auto: false,
	onError() {},
})

function reload() {
	error.value = ''
	start.value = 0
	loading.value = true
	list.fetch()
	ringkas.fetch()
}

function muatLagi() {
	start.value += PER_HALAMAN
	loading.value = true
	list.fetch()
}

function geserPeriode(arah) {
	if (bulan.value == null) return
	let b = bulan.value + arah
	let t = tahun.value
	if (b < 1) {
		b = 12
		t -= 1
	} else if (b > 12) {
		b = 1
		t += 1
	}
	bulan.value = b
	tahun.value = t
	// Tanggal terpilih milik periode lama; membawanya hanya menghasilkan daftar kosong.
	hapusTanggal(false)
	reload()
}

function pilihKelompok(k) {
	kelompokAktif.value = kelompokAktif.value === k ? '' : k
	reload()
}

function pilihStatus(s) {
	sheetStatus.value = false
	if (status.value === s) return
	status.value = s
	reload()
}

function hapusTanggal(muatUlang = true) {
	tanggal.value = ''
	if (route.query.tanggal || route.query.buka) {
		router.replace({ query: asalKehadiran ? { kehadiran: asalKehadiran } : {} })
	}
	if (muatUlang) reload()
}

async function bukaDetail(row) {
	// Lembar dibuka SEKARANG dari data kartu; riwayat menyusul dari server.
	detail.value = { ...row }
	siapkanForm(row)

	const d = await detailRes.fetch({ name: row.name })
	// Balasan bisa datang setelah lembar ditutup atau kartu lain dibuka.
	if (!d || detail.value?.name !== row.name) return
	detail.value = { ...detail.value, ...d }
	// Dibuka dari tautan (?buka=) kartunya belum ada, jadi form baru bisa
	// diisi alasan lama setelah detail datang — selama belum diketik.
	if (!row.jenis && !alasan.value) siapkanForm(d)
}

function siapkanForm(row) {
	// Pengajuan ulang membawa alasan lama sebagai titik awal — yang ditolak
	// biasanya perlu diperjelas, bukan ditulis dari nol.
	alasan.value = row.alasan || ''
	lampiran.value = row.lampiran || ''
	galatKirim.value = ''
}

function tutupDetail() {
	if (mengirim.value) return
	detail.value = null
}

async function kirim() {
	if (!alasan.value.trim() || mengirim.value || !detail.value) return
	galatKirim.value = ''
	mengirim.value = true
	try {
		await refreshCsrfToken()
		const hasil = await kirimRes.submit({
			name: detail.value.name,
			alasan: alasan.value.trim(),
			lampiran: lampiran.value || null,
		})
		detail.value = hasil
		notifySuccess('Alasan terkirim, menunggu approval.')
		reload()
	} catch (e) {
		galatKirim.value = e?.messages?.[0] || e?.message || String(e)
	} finally {
		mengirim.value = false
	}
}

async function unggah(e) {
	const file = e.target.files?.[0]
	if (!file) return
	if (file.size > MAKS_MB * 1024 * 1024) {
		galatKirim.value = `Ukuran file maksimal ${MAKS_MB} MB.`
		e.target.value = ''
		return
	}

	mengunggah.value = true
	galatKirim.value = ''
	try {
		const fd = new FormData()
		fd.append('file', file, file.name)
		fd.append('upload_doctype', 'Perbaikan Absen')
		fd.append('is_private', '1')
		const res = await fetch('/api/method/upload_file', {
			method: 'POST',
			credentials: 'include',
			headers: {
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: fd,
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(json?.exception || json?.message || `HTTP ${res.status}`)
		lampiran.value = json.message?.file_url || ''
	} catch (err) {
		galatKirim.value = err.message || String(err)
		e.target.value = ''
	} finally {
		mengunggah.value = false
	}
}

onMounted(async () => {
	await refreshCsrfToken()
	reload()
	// Dibuka dari detail Kehadiran dengan satu record yang perlu diisi.
	if (route.query.buka) bukaDetail({ name: String(route.query.buka) })
})
</script>
